from pathlib import Path
import json, html
p=Path(__file__).resolve().parents[1]
g=json.loads((p/'architecture/graph.json').read_text()); gates=json.loads((p/'release/gates.json').read_text())
def encode(o):return json.dumps(o,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
css='''<style>:root{color-scheme:dark;--bg:#081321;--panel:#112338;--border:#29435c;--ink:#eaf2fd;--muted:#9cbbd5;--accent:#66d3fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui}header{padding:30px max(22px,5vw);border-bottom:1px solid var(--border);background:#0e2238}main{max-width:1320px;margin:auto;padding:24px}h1{font-size:clamp(1.6rem,3vw,2.5rem);margin:4px 0}h2{font-size:1.2rem}p,small{color:var(--muted)}.pill{display:inline-block;padding:4px 10px;border:1px solid var(--border);border-radius:30px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.card{padding:18px;background:var(--panel);border:1px solid var(--border);border-radius:12px;margin:12px 0}.stat{font-size:2rem;font-weight:700}.passed{color:#73dbac}.held{color:#ffd18a}button,input,select{font:inherit;border:1px solid #456989;background:#173450;color:var(--ink);border-radius:7px;padding:9px}button{cursor:pointer}button:hover{background:#24517a}input{width:100%;max-width:480px}table{border-collapse:collapse;width:100%}th,td{padding:10px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}tr[hidden]{display:none}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0a1b2e;padding:14px;border-radius:8px}code{color:#a3dafa}svg{max-width:100%;width:100%;height:470px;background:#0a1b2e;border-radius:9px}svg line{stroke:#537087}svg circle{fill:#28638b;stroke:#95ddff;stroke-width:2}svg text{fill:#eaf2fd;font-size:11px}a{color:#91dafb}.notice{border-left:3px solid #69c8f0;padding-left:14px;margin:20px 0}@media(max-width:650px){main{padding:13px}header{padding:18px}table{font-size:12px}th,td{padding:6px}}</style>'''
base='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'">{title}{css}</head><body>{content}<script id="canonical-graph" type="application/json">{graph}</script><script id="release-gates" type="application/json">{gates}</script>{js}</body></html>'''
common='''<script>"use strict";const graph=JSON.parse(document.getElementById('canonical-graph').textContent),gates=JSON.parse(document.getElementById('release-gates').textContent);const escapeText=(x)=>String(x);function el(tag,text){let e=document.createElement(tag);if(text!==undefined)e.textContent=escapeText(text);return e;}function graphDraw(target){const ns='http://www.w3.org/2000/svg';const svg=document.getElementById(target);const nodes=graph.components.map((n,i)=>({...n,x:110+(i%4)*235,y:65+Math.floor(i/4)*108}));let scale=1;function shape(tag,props){const e=document.createElementNS(ns,tag);Object.entries(props).forEach(([k,v])=>e.setAttribute(k,String(v)));return e;}function draw(){svg.replaceChildren();let layer=shape('g',{transform:`scale(${scale})`});svg.append(layer);graph.edges.forEach(edge=>{const a=nodes.find(n=>n.id===edge.from),b=nodes.find(n=>n.id===edge.to);if(a&&b)layer.append(shape('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y}));});nodes.forEach(n=>{let c=shape('circle',{cx:n.x,cy:n.y,r:25,tabindex:0,role:'button','aria-label':n.id});let t=shape('text',{x:n.x,y:n.y+43,'text-anchor':'middle'});t.textContent=n.id;c.addEventListener('click',()=>{document.getElementById('graph-detail').textContent=JSON.stringify({node:n.id,edges:graph.edges.filter(e=>e.from===n.id||e.to===n.id),requirements:graph.requirements.filter(r=>r.implementation.toLowerCase().includes(n.id.toLowerCase()))},null,2)});layer.append(c,t);});}draw();document.getElementById('zoom-in').onclick=()=>{scale=Math.min(1.7,scale+.1);draw()};document.getElementById('zoom-out').onclick=()=>{scale=Math.max(.55,scale-.1);draw()};}</script>'''
req_content='''<header><small class="pill">REQUIREMENTS ENGINEERING · DESIGN STAGE</small><h1>HMT DevSecOps · Requirements and architecture</h1><p>Intent, constraints, traceability, trade-offs, and adversarial impact. Source: architecture/graph.json.</p></header><main><div class="grid"><article class="card"><small>Requirements in scope</small><div class="stat" id="req-count"></div></article><article class="card"><small>Architecture components</small><div class="stat" id="component-count"></div></article><article class="card"><small>Tool operations</small><div class="stat">10</div></article></div><div class="notice">This is a design-stage projection. A requirement's implementation link does not certify its runtime. Consult the separate close-out report for observed gate states.</div><section class="card"><h2>Requirement-to-witness matrix</h2><input id="search" aria-label="Filter requirements" placeholder="Filter by requirement, family, implementation, witness"><div style="overflow:auto"><table><thead><tr><th>ID</th><th>Family</th><th>Requirement</th><th>Implementation</th><th>Witness</th></tr></thead><tbody id="req-rows"></tbody></table></div></section><section class="card"><h2>Adversarial change-impact query</h2><label for="impact-id">Requirement ID</label> <select id="impact-id"></select> <button id="impact">Inspect affected seams</button><pre id="impact-result" aria-live="polite">Select a requirement.</pre></section><section class="card"><h2>Dependency graph</h2><p>Click a component for edges. Zoom changes display only.</p><button id="zoom-in">Zoom +</button> <button id="zoom-out">Zoom −</button><svg id="architecture-svg" viewBox="0 0 1060 520" role="img" aria-label="Architecture dependency graph"></svg><pre id="graph-detail">Select a node.</pre></section><section class="card"><h2>PACE-T and trade hypotheses</h2><div id="pace" class="grid"></div><div style="overflow:auto"><table><thead><tr><th>Candidate</th><th>Role</th><th>Benefit</th><th>Constraint</th></tr></thead><tbody id="trade"></tbody></table></div></section></main>'''
req_js=common+'''<script>document.getElementById('req-count').textContent=graph.requirements.length;document.getElementById('component-count').textContent=graph.components.length;const rows=document.getElementById('req-rows');for(const r of graph.requirements){const tr=el('tr');for(const k of ['id','family','statement','implementation','verification'])tr.append(el('td',r[k]));tr.dataset.search=Object.values(r).join(' ').toLowerCase();rows.append(tr);const o=el('option',r.id+' · '+r.family);o.value=r.id;document.getElementById('impact-id').append(o)}document.getElementById('search').oninput=e=>{for(const tr of rows.children)tr.hidden=!tr.dataset.search.includes(e.target.value.toLowerCase())};document.getElementById('impact').onclick=()=>{const r=graph.requirements.find(x=>x.id===document.getElementById('impact-id').value);document.getElementById('impact-result').textContent=JSON.stringify({requirement:r.id,source:r.statement,impacted_implementation:r.implementation,mandatory_regression:r.verification,downstream:'Contract, PACE-T guards, related evidence and authority reviewed before promotion',decision:'CHANGE_INVALIDATES_PRIOR_CLAIM_UNTIL_REVERIFIED'},null,2)};for(const [k,v] of Object.entries(graph.pace)){const c=el('div');c.className='card';c.append(el('strong',k),el('p',v));document.getElementById('pace').append(c)}for(const x of graph.trade_study){const tr=el('tr');for(const k of ['candidate','role','benefit','constraint'])tr.append(el('td',x[k]));document.getElementById('trade').append(tr)}graphDraw('architecture-svg');</script>'''
close_content='''<header><small class="pill">RELEASE CLOSE-OUT · OBSERVED EVIDENCE STAGE</small><h1>HMT DevSecOps · System state snapshot</h1><p>Evidence dispositions, operational readiness, regression history, and deploy qualification. Same canonical architecture graph; distinct verification-stage lens.</p></header><main><div class="grid"><article class="card"><small>Recorded gates</small><div id="total" class="stat"></div></article><article class="card"><small>PASS</small><div class="stat passed" id="pass"></div></article><article class="card"><small>HOLD</small><div class="stat held" id="hold"></div></article><article class="card"><small>Pending physical qualification</small><div class="stat held">Separate</div></article></div><div class="notice">A configured service or matching source does not constitute a deployed runtime witness. Unrun gates remain HOLD. The three reconciliation patches require their own regression receipts.</div><section class="card"><h2>Gate and evidence register</h2><label for="filter">Disposition</label> <select id="filter"><option value="ALL">All</option><option value="PASS">PASS</option><option value="HOLD">HOLD</option><option value="FAIL">FAIL</option></select><div style="overflow:auto"><table><thead><tr><th>Gate</th><th>Status</th><th>Observation</th><th>Evidence</th></tr></thead><tbody id="gate-rows"></tbody></table></div></section><section class="card"><h2>Authority and operation checkpoints</h2><div class="grid"><article><h3>Observe</h3><p>Tool reads, hash records, health, and metrics never grant mutation authority.</p></article><article><h3>Admit</h3><p>Typed ingress, bearer authorization, body bound, per-worker capacity semaphore, and explicit operation grant.</p></article><article><h3>Execute</h3><p>Approved operation returns receipts. Capacity and cancellation never create a new execution grant.</p></article><article><h3>Recover</h3><p>Inspect uncertain state and correlate evidence before any restart, retry, or authority transition.</p></article></div></section><section class="card"><h2>Evidence-to-component dependency graph</h2><button id="zoom-in">Zoom +</button> <button id="zoom-out">Zoom −</button><svg id="close-svg" viewBox="0 0 1060 520" role="img" aria-label="Operational dependency graph"></svg><pre id="graph-detail">Select a component to inspect its dependencies.</pre></section><section class="card"><h2>RRCA and follow-up</h2><p>Reconciliation IDs: RRCA-HTML-001, RRCA-METRICS-002, RRCA-CAPACITY-003. See <code>release/rrca.md</code> and <code>evidence/patch_regression.txt</code>.</p><p>Operator instructions: <code>Runbook.md</code>. Admission evidence: <code>release/gates.json</code>. Baseline truth: <code>architecture/graph.json</code>.</p></section></main>'''
close_js=common+'''<script>document.getElementById('total').textContent=gates.length;document.getElementById('pass').textContent=gates.filter(x=>x.disposition==='PASS').length;document.getElementById('hold').textContent=gates.filter(x=>x.disposition==='HOLD').length;const target=document.getElementById('gate-rows');for(const g of gates){const row=el('tr');row.dataset.status=g.disposition;for(const k of ['gate_id','disposition','reason','evidence_ref'])row.append(el('td',g[k]));target.append(row)}document.getElementById('filter').onchange=e=>{for(const tr of target.children)tr.hidden=e.target.value!=='ALL'&&tr.dataset.status!==e.target.value};graphDraw('close-svg');</script>'''
for file,title,content,js in [('HMT_DevSecOps_Requirements_v1.0.0.html','HMT DevSecOps | Requirements Engineering',req_content,req_js),('HMT_DevSecOps_Closeout_v1.0.0.html','HMT DevSecOps | Release Close-out',close_content,close_js)]:
 (p/file).write_text(base.format(title='<title>'+html.escape(title)+'</title>',css=css,content=content,graph=encode(g),gates=encode(gates),js=js),encoding='utf8')
